import csv, io, json, re, sys, calendar
import xml.etree.ElementTree as ET
from datetime import datetime, timezone, timedelta, date
from decimal import Decimal, ROUND_HALF_UP
from fractions import Fraction
from pathlib import Path

LAYOUT_DIR = Path(__file__).resolve().parent.parent / "docs" / "layouts"
PRIORITY = ["central", "south", "east", "river", "north", "west"]
KG = {"kg": Fraction(1), "lb": Fraction("0.45359237"), "oz": Fraction("0.028349523125"),
      "g": Fraction("0.001")}
COUNTED = {"delivered", "delivered_late"}
ID_RE = re.compile(r"^\s*SH\D*?(\d+)\s*$", re.I)
MONTHS = {m.lower(): i for i, m in enumerate(calendar.month_abbr) if m}
