            t = tz[1:].replace(":", "")
            dt -= sign * timedelta(hours=int(t[:2]), minutes=int(t[2:]))
        return dt.year, dt.month
    m = re.fullmatch(r"(\d{1,2})[ \-]([A-Za-z]+)[ \-,]+(\d{4})", s)
    if m and m[2].lower() in MONTHS:
        return int(m[3]), MONTHS[m[2].lower()]
    m = re.fullmatch(r"([A-Za-z]+)\.?\s+(\d{1,2}),?\s+(\d{4})", s)
    if m and m[1].lower() in MONTHS:
        return int(m[3]), MONTHS[m[1].lower()]
    m = re.fullmatch(r"(\d{1,4})([/.\-])(\d{1,2})\2(\d{2,4})", s)
    if m:
        a, sep, b, c = int(m[1]), m[2], int(m[3]), int(m[4])
        if len(m[1]) == 4:
            return a, b
        if fmt:
            try:
                d = date_from_fmt(s, fmt)
                if d: return d.year, d.month
            except Exception:
                pass
        if a > 12: return c, b          # DD first
        if b > 12: return c, a          # MM first
        if sep == ".": return c, b
        return c, a                     # slash default MM/DD
    raise ValueError("unparsable date: " + s)


def find_datefmt(text):
    m = re.search(r"\b((?:YYYY|YY|MM|DD)[/.\-](?:YYYY|YY|MM|DD)[/.\-](?:YYYY|YY|MM|DD))\b", text, re.I)
    return m[1] if m else None


