    wc = next(i for i, h in enumerate(low) if h.startswith("weight") or h.startswith("wt"))
    sc = next(i for i, h in enumerate(low) if h.startswith("ship") or h in ("date",))
    stc = next(i for i, h in enumerate(low) if h.startswith("status"))
