        f = lambda k: l[fields[k][0]:fields[k][1]]
        rid = f("id").strip()
        if not ID_RE.match(rid): continue
        st = f("status").strip()
        out.append((rid, yddd(f("shipped")), int(f("weight")) * scale, codes.get(st.upper(), st)))
    return out


def read_file(p):
    ext = p.suffix.lower()
    if ext == ".xml": return read_xml(p)
    if ext in (".jsonl", ".json", ".ndjson"): return read_json(p)
    with open(p, encoding="utf-8-sig", errors="replace") as fh:
        first = fh.readline()
    if first.startswith("#LAYOUT"): return read_fw(p)
    if ext in (".csv", ".tsv"): return read_delim(p, ext)
    if first.lstrip().startswith("{"): return read_json(p)
    if first.lstrip().startswith("<"): return read_xml(p)
    return read_delim(p, ext)


def main():
    data, outf = Path(sys.argv[1]), Path(sys.argv[2])
    files = sorted(p for p in data.iterdir() if p.is_file() and not p.name.startswith("."))
    rank = lambda p: (PRIORITY.index(p.stem) if p.stem in PRIORITY else len(PRIORITY), p.stem)
    depots = {p.stem: {"shipments": 0, "kg": Fraction(0)} for p in files}
    kept = {}
    seen_in = {}
    for p in sorted(files, key=rank):
