            num = int(m[1])
            seen_in.setdefault(num, set()).add(p.stem)
            if num not in kept:
                kept[num] = (p.stem, ym, kg, status)
    months = {}
    for dep, ym, kg, status in kept.values():
        if norm_status(status) in COUNTED:
            depots[dep]["shipments"] += 1
            depots[dep]["kg"] += kg
            k = "%04d-%02d" % ym
