    res = {
        "depots": {d: {"shipments": v["shipments"],
                       "total_kg": float(Decimal(v["kg"].numerator) / Decimal(v["kg"].denominator)
                                         if False else
                                         (Decimal(v["kg"].numerator * 10**30 // v["kg"].denominator) / Decimal(10**30))
                                         .quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))}
                   for d, v in sorted(depots.items())},
        "by_month": dict(sorted(months.items())),
        "duplicates_resolved": sum(1 for s in seen_in.values() if len(s) > 1),
    }
    outf.write_text(json.dumps(res, indent=2) + "\n")


if __name__ == "__main__":
    main()
