            fields[m[1]] = (int(m[2]) - 1, int(m[3]), m[4])
            continue
        m = re.match(r"^\s+([A-Z])\s{2,}(\S.*?)\s*$", line)
        if m:
            codes[m[1]] = norm_status(m[2])
    wdesc = fields["weight"][2].lower()
    if "hundredth" in wdesc:
        scale = Fraction(1, 100) * KG[find_unit(wdesc.split("of a")[-1]) or "kg"]
    else:
        scale = KG[find_unit(wdesc) or "g"]
    return fields, codes, scale


def read_fw(path):
    lines = Path(path).read_text(encoding="utf-8-sig").splitlines()
    m = re.match(r"#LAYOUT\s+(\S+)", lines[0])
    fields, codes, scale = parse_layout(m[1])
    out = []
    for l in lines:
        if not l.strip() or l.startswith("#"): continue
        f = lambda k: l[fields[k][0]:fields[k][1]]
        rid = f("id").strip()
        if not ID_RE.match(rid): continue
        st = f("status").strip()
        out.append((rid, yddd(f("shipped")), int(f("weight")) * scale, codes.get(st.upper(), st)))
    return out


def read_file(p):
    ext = p.suffix.lower()
    with open(p, encoding="utf-8-sig", errors="replace") as fh:
        first = fh.readline()
    if first.startswith("#LAYOUT"): return read_fw(p)
    if ext == ".xml": return read_xml(p)
    if ext in (".jsonl", ".json", ".ndjson"): return read_json(p)
    if first.lstrip().startswith("{"): return read_json(p)
    if first.lstrip().startswith("<"): return read_xml(p)
    return read_delim(p, ext)


def round2(fr):
    return math.floor(fr * 100 + Fraction(1, 2)) / 100


def main():
    data, outf = Path(sys.argv[1]), Path(sys.argv[2])
    files = [p for p in data.iterdir() if p.is_file() and not p.name.startswith(".")]
    rank = lambda p: (PRIORITY.index(p.stem) if p.stem in PRIORITY else len(PRIORITY), p.stem)
    depots = {p.stem: {"n": 0, "kg": Fraction(0)} for p in files}
    kept, seen_in = {}, {}
    for p in sorted(files, key=rank):
        for rid, ym, kg, status in read_file(p):
            num = int(ID_RE.match(rid)[1])
            seen_in.setdefault(num, set()).add(p.stem)
            if num not in kept:
                kept[num] = (p.stem, ym, kg, status)
    months = {}
    for dep, ym, kg, status in kept.values():
        if norm_status(status) in COUNTED:
            depots[dep]["n"] += 1
            depots[dep]["kg"] += kg
            k = "%04d-%02d" % ym
            months[k] = months.get(k, 0) + 1
    res = {
        "depots": {d: {"shipments": v["n"], "total_kg": round2(v["kg"])} for d, v in sorted(depots.items())},
        "by_month": dict(sorted(months.items())),
        "duplicates_resolved": sum(1 for s in seen_in.values() if len(s) > 1),
    }
    outf.write_text(json.dumps(res, indent=2) + "\n")


if __name__ == "__main__":
    main()
EOF
